  'Share cancelled.' => 'බෙදාගැනීම අවලංගු කරන ලදී.',
  'Notifications muted for this profile.' => 'මෙම පැතිකඩ සඳහා දැනුම්දීම් නිහඬ කර ඇත.',
  'Notifications enabled for this profile.' => 'මෙම පැතිකඩ සඳහා දැනුම්දීම් සබල කර ඇත.',
  'Profile added to favorites.' => 'ප්‍රියතමයන් වෙත පැතිකඩ එක් කරන ලදී.',
  'Profile removed from favorites.' => 'ප්‍රියතමයන් වෙතින් පැතිකඩ ඉවත් කරන ලදී.',
  'Profile reported for review.' => 'පැතිකඩ සමාලෝචනය සඳහා වාර්තා කර ඇත.',
  'User blocked. Their content and notifications are hidden.' => 'පරිශීලක අවහිර කර ඇත. ඒවායේ අන්තර්ගතය සහ දැනුම්දීම් සඟවා ඇත.',
  'User unblocked.' => 'පරිශීලක අවහිර කිරීම ඉවත් කරන ලදී.',
  'Unblock this user before sending a message.' => 'පණිවිඩයක් යැවීමට පෙර මෙම පරිශීලකයා අවහිර නොකරන්න.',
  'Message composer opened.' => 'පණිවිඩ රචකයා විවෘත කරන ලදී.',
  'About' => 'ගැන',
