  'This channel has not added an about section yet.' => 'මෙම නාලිකාව තවම ගැන කොටසක් එකතු කර නැත.',
  'Admin' => 'පරිපාලක',
  'Dashboard' => 'උපකරණ පුවරුව',
  'Users' => 'පරිශීලකයන්',
  'Reports' => 'වාර්තා',
