  'Monitor platform activity, moderation, revenue, and system health.' => 'වේදිකා ක්‍රියාකාරකම්, මධ්‍යස්ථ කිරීම, ආදායම සහ පද්ධති සෞඛ්‍යය නිරීක්ෂණය කරන්න.',
  'Manage and monitor platform users, permissions, and activity.' => 'වේදිකා පරිශීලකයන්, අවසර සහ ක්‍රියාකාරකම් කළමනාකරණය සහ අධීක්ෂණය.',
  'Manage creators, channel performance, verification, and creator growth.' => 'නිර්මාපකයින්, නාලිකා කාර්ය සාධනය, සත්‍යාපනය සහ නිර්මාපක වර්ධනය කළමනාකරණය කරන්න.',
  'Manage videos, shorts, posts, and content moderation across the platform.' => 'වේදිකාව හරහා වීඩියෝ, කෙටිකතා, පළ කිරීම් සහ අන්තර්ගත මධ්‍යස්ථකරණය කළමනාකරණය කරන්න.',
  'Monitor live sessions, scheduling, stream health, and live moderation.' => 'සජීවී සැසි, කාලසටහන්ගත කිරීම, ප්‍රවාහ සෞඛ්‍යය සහ සජීවී මධ්‍යස්ථභාවය නිරීක්ෂණය කරන්න.',
  'Review flagged content, user complaints, and platform safety incidents.' => 'සලකුණු කළ අන්තර්ගතය, පරිශීලක පැමිණිලි සහ වේදිකා ආරක්ෂණ සිදුවීම් සමාලෝචනය කරන්න.',
  'Track revenue, payouts, subscriptions, ads, tips, and creator earnings.' => 'ආදායම, ගෙවීම්, දායකත්වයන්, දැන්වීම්, ඉඟි, සහ නිර්මාපක ඉපැයීම් නිරීක්ෂණය කරන්න.',
  'Analyze platform growth, viewer behavior, engagement, and content performance.' => 'වේදිකා වර්ධනය, නරඹන්නන්ගේ හැසිරීම, නියැලීම සහ අන්තර්ගත කාර්ය සාධනය විශ්ලේෂණය කරන්න.',
  'Manage support tickets, help requests, escalations, and response quality.' => 'සහාය ප්‍රවේශපත්‍ර, උපකාර ඉල්ලීම්, උත්සන්න කිරීම් සහ ප්‍රතිචාර ගුණත්වය කළමනාකරණය කරන්න.',
  'Manage admin roles, access levels, team members, and security permissions.' => 'පරිපාලක භූමිකාවන්, ප්‍රවේශ මට්ටම්, කණ්ඩායම් සාමාජිකයින් සහ ආරක්ෂක අවසර කළමනාකරණය කරන්න.',
  'Configure platform preferences, integrations, security, storage, and system behavior.' => 'වේදිකා මනාප, ඒකාබද්ධ කිරීම්, ආරක්ෂාව, ගබඩා කිරීම සහ පද්ධති හැසිරීම් වින්‍යාස කරන්න.',
  'Loading admin data...' => 'සැබෑ පරිපාලක දත්ත පූරණය කරමින්...',
  'Sign in with an admin account to view this page.' => 'මෙම පිටුව බැලීමට පරිපාලක ගිණුමක් සමඟින් පුරනය වන්න.',
