  'Create channel profiles for generated users' => 'ජනනය කළ පරිශීලකයින් සඳහා නාලිකා පැතිකඩ සාදන්න',
  'Generate random avatars' => 'අහඹු අවතාර උත්පාදනය කරන්න',
  'Invite user' => 'පරිශීලකයාට ආරාධනා කරන්න',
