  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'තවමත් ඔබේ නාලිකාව සොයාගෙන නැති නරඹන්නන් වෙත ළඟා වීමට කෙටි සිරස් වීඩියෝ සාදන්න.',
