  'Ask a question in your next upload and reply quickly when comments arrive.' => 'ඔබගේ ඊළඟ උඩුගත කිරීමේදී ප්‍රශ්නයක් අසන්න සහ අදහස් පැමිණි විට ඉක්මනින් පිළිතුරු දෙන්න.',
  'View comments' => 'අදහස් බලන්න',
  'Improve public reach' => 'මහජන ප්‍රවේශය වැඩි දියුණු කරන්න',
  'Keep strong videos visible and refresh weak titles.' => 'ශක්තිමත් වීඩියෝ දෘශ්‍යමානව තබා දුර්වල මාතෘකා නැවුම් කරන්න.',
