  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'මාතෘකා, ටැග්, දෘශ්‍යතාව සහ සිඟිති රූ පියවර සමඟ නව උඩුගත කිරීමක් ආරම්භ කරන්න.',
  'Shorts studio' => 'කෙටි චිත්රාගාරය',
  'Create short videos for faster discovery and mobile viewers.' => 'වේගවත් සොයාගැනීම් සහ ජංගම බලන්නන් සඳහා කෙටි වීඩියෝ සාදන්න.',
  'Content manager' => 'අන්තර්ගත කළමනාකරු',
  'Review visibility, monetization, comments, and performance in one place.' => 'එක තැනක දෘශ්‍යතාව, මුදල් ඉපැයීම, අදහස් සහ කාර්ය සාධනය සමාලෝචනය කරන්න.',
  'Analytics review' => 'විශ්ලේෂණ සමාලෝචනය',
  'Track views, likes, comments, publishing status, and trends.' => 'බැලීම්, කැමැත්ත, අදහස්, ප්‍රකාශන තත්ත්වය සහ ප්‍රවණතා නිරීක්ෂණය කරන්න.',
  'Channel profile' => 'නාලිකා පැතිකඩ',
  'Update your bio, channel details, and public creator presence.' => 'ඔබගේ ජීව දත්ත, නාලිකා විස්තර සහ පොදු නිර්මාපක පැමිණීම යාවත්කාලීන කරන්න.',
  'Audience building' => 'ප්රේක්ෂක ගොඩනැගීම',
  'Study subscribers, comments, and what viewers respond to most.' => 'ග්‍රාහකයින්, අදහස් සහ නරඹන්නන් වැඩිපුරම ප්‍රතිචාර දක්වන දේ අධ්‍යයනය කරන්න.',
  'Top content to learn from' => 'ඉගෙන ගැනීමට ඉහළම අන්තර්ගතය',
  'Upload videos to unlock performance lessons.' => 'කාර්ය සාධන පාඩම් අගුළු ඇරීමට වීඩියෝ උඩුගත කරන්න.',
  'Tips to reach more viewers' => 'වැඩි නරඹන්නන් වෙත ළඟා වීමට ඉඟි',
  'Creator checklist' => 'නිර්මාපක පිරික්සුම් ලැයිස්තුව',
  'Hook viewers in the first 3 seconds' => 'පළමු තත්පර 3 තුළ නරඹන්නන් සම්බන්ධ කරන්න',
  'Open with the result, conflict, or visual payoff before adding context.' => 'සන්දර්භය එක් කිරීමට පෙර ප්‍රතිඵලය, ගැටුම හෝ දෘශ්‍ය ගෙවීම සමඟ විවෘත කරන්න.',
  'Make titles searchable' => 'මාතෘකා සෙවිය හැකි බවට පත් කරන්න',
  'Use the exact words viewers would type, then keep the promise in the video.' => 'නරඹන්නන් ටයිප් කරන නියම වචන භාවිතා කරන්න, ඉන්පසු වීඩියෝවේ පොරොන්දුව තබා ගන්න.',
  'Convert shorts into sessions' => 'කෙටි කලිසම් සැසි බවට පරිවර්තනය කරන්න',
  'Pin a comment or description link from each short to a related full video.' => 'එක් එක් කෙටියෙන් අදාළ සම්පූර්ණ වීඩියෝවකට අදහසක් හෝ විස්තර සබැඳියක් අමුණන්න.',
  'Refresh underperforming uploads' => 'අඩු ක්‍රියාකාරී උඩුගත කිරීම් නැවුම් කරන්න',
  'Update thumbnails and titles after you have enough impressions to compare.' => 'ඔබට සංසන්දනය කිරීමට ප්‍රමාණවත් ප්‍රතිරූප ඇති වූ පසු සිඟිති රූ සහ මාතෘකා යාවත්කාලීන කරන්න.',
  'Upload source' => 'මූලාශ්‍රය උඩුගත කරන්න',
  'Choose a local video file or import a public video from an enabled provider.' => 'දේශීය වීඩියෝ ගොනුවක් තෝරන්න හෝ සබල කළ සැපයුම්කරුවෙකුගෙන් පොදු වීඩියෝවක් ආයාත කරන්න.',
  'Local upload' => 'දේශීය උඩුගත කිරීම',
  'Import from URL' => 'URL වෙතින් ආයාත කරන්න',
  'Import video from URL' => 'URL වෙතින් වීඩියෝව ආයාත කරන්න',
  'Select an enabled service and paste a public video URL. PlayHub will import it into the normal processing queue.' => 'සබල කළ සේවාවක් තෝරා පොදු වීඩියෝ URL එකක් අලවන්න. PlayHub එය සාමාන්‍ය සැකසුම් පෝලිමට ආයාත කරනු ඇත.',
  'Service' => 'සේවාව',
  'Video URL' => 'වීඩියෝ URL',
  'Direct video URL' => 'සෘජු වීඩියෝ URL',
  'YouTube' => 'YouTube',
  'Vimeo' => 'Vimeo',
  'Dailymotion' => 'Dailymotion',
  'Imports a public MP4, MOV, WEBM, MKV, AVI, or M4V file URL.' => 'පොදු MP4, MOV, WEBM, MKV, AVI, හෝ M4V ගොනු URL ආයාත කරන්න.',
  'Requires a downloader command such as yt-dlp for media import.' => 'මාධ්‍ය ආයාත කිරීම සඳහා yt-dlp වැනි බාගැනීම් විධානයක් අවශ්‍ය වේ.',
  'Import queue' => 'ආනයන පෝලිම',
  'Generated after import' => 'ආනයනය කිරීමෙන් පසු ජනනය වේ',
  'A thumbnail is created during processing.' => 'සැකසීමේදී සිඟිති රූපයක් සාදනු ලැබේ.',
  'Complete the import details first.' => 'මුලින්ම ආනයන විස්තර සම්පූර්ණ කරන්න.',
  'Import source' => 'ආයාත මූලාශ්රය',
  'Import summary' => 'ආයාත සාරාංශය',
  'Source URL' => 'මූලාශ්‍ර URL',
  'Video imported' => 'වීඩියෝව ආනයනය කරන ලදී',
  'Your video was imported and processing has started.' => 'ඔබගේ වීඩියෝව ආයාත කර ඇති අතර සැකසීම ආරම්භ කර ඇත.',
  'Import Video' => 'වීඩියෝව ආනයනය කරන්න',
  'Import a public video URL, customize its details, and publish it through the normal processing pipeline.' => 'පොදු වීඩියෝ URL එකක් ආයාත කරන්න, එහි විස්තර අභිරුචිකරණය කරන්න, සහ සාමාන්‍ය සැකසුම් නල මාර්ගය හරහා එය ප්‍රකාශ කරන්න.',
  'Video Import' => 'වීඩියෝ ආනයනය',
  'Enable importing videos from supported external providers.' => 'සහාය දක්වන බාහිර සැපයුම්කරුවන්ගෙන් වීඩියෝ ආයාත කිරීම සබල කරන්න.',
  'Downloader Command' => 'බාගැනීම් විධානය',
  'YouTube Data API key' => 'YouTube දත්ත API යතුර',
  'Vimeo access token' => 'Vimeo ප්රවේශ ටෝකනය',
  'Dailymotion API key' => 'Dailymotion API යතුර',
  'API Key' => 'API යතුර',
  'Not required' => 'අවශ්ය නොවේ',
  'Save Import Settings' => 'ආයාත සැකසුම් සුරකින්න',
  'Video import settings saved.' => 'වීඩියෝ ආයාත සැකසීම් සුරකින ලදී.',
  'Video import started.' => 'වීඩියෝ ආයාත කිරීම ආරම්භ විය.',
  'This video import provider is disabled.' => 'මෙම වීඩියෝ ආයාත සැපයුම්කරු අබල කර ඇත.',
  'Video import provider is disabled.' => 'වීඩියෝ ආයාත සැපයුම්කරු අබල කර ඇත.',
  'Direct imports must use a supported video file URL.' => 'සෘජු ආයාත කිරීම් සඳහා සහාය දක්වන වීඩියෝ ගොනු URL එකක් භාවිත කළ යුතුය.',
  'Cannot open remote video URL.' => 'දුරස්ථ වීඩියෝ URL විවෘත කළ නොහැක.',
  'Cannot prepare imported video file.' => 'ආනයනික වීඩියෝ ගොනුව සකස් කළ නොහැක.',
  'Cannot read remote video file.' => 'දුරස්ථ වීඩියෝ ගොනුව කියවිය නොහැක.',
  'Imported video exceeds the maximum upload size.' => 'ආයාත කළ වීඩියෝව උපරිම උඩුගත කිරීමේ ප්‍රමාණය ඉක්මවයි.',
  'Remote video file is empty.' => 'දුරස්ථ වීඩියෝ ගොනුව හිස්ය.',
  'Video import downloader command is not configured.' => 'වීඩියෝ ආයාත බාගැනීම් විධානය වින්‍යාස කර නොමැත.',
  'Downloader did not create an importable video file.' => 'බාගත කරන්නා ආනයනය කළ හැකි වීඩියෝ ගොනුවක් නිර්මාණය කළේ නැත.',
  'Import URL is invalid.' => 'ආයාත URL වලංගු නොවේ.',
  'Import URL must use HTTP or HTTPS.' => 'ආයාත URL HTTP හෝ HTTPS භාවිතා කළ යුතුය.',
  'Import URL host is invalid.' => 'ආයාත URL සත්කාරක වලංගු නොවේ.',
  'Import URL does not match the selected provider.' => 'ආයාත URL තෝරාගත් සැපයුම්කරුට නොගැලපේ.',
  'Import URL host cannot be resolved.' => 'ආයාත URL ධාරකය විසඳිය නොහැක.',
  'Import URL must resolve to a public host.' => 'ආයාත URL පොදු සත්කාරක සමාගමකට විසඳිය යුතුය.',
  'Unknown video import provider.' => 'නොදන්නා වීඩියෝ ආයාත සපයන්නා.',
  'Saves a public video file URL and plays it from the original URL.' => 'පොදු වීඩියෝ ගොනු URL එකක් සුරකින අතර මුල් URL එකෙන් එය වාදනය කරයි.',
  'Fetches YouTube details and plays with the YouTube embed player.' => 'YouTube විස්තර ලබාගෙන YouTube embed player සමඟ සෙල්ලම් කරයි.',
  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'Vimeo විස්තර ලබාගෙන Vimeo embed player සමඟ සෙල්ලම් කරයි.',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'Dailymotion විස්තර ලබාගෙන Dailymotion embed player සමඟ සෙල්ලම් කරයි.',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'සබල කළ සේවාවක් තෝරා පොදු වීඩියෝ URL එකක් අලවන්න. PlayHub විසින් විස්තර ලබාගෙන එය මුල් සැපයුම්කරුගෙන් වාදනය කරනු ඇත.',
