  'Saving provider video' => 'සපයන්නාගේ වීඩියෝව සුරැකීම',
  'Fetched from provider' => 'සපයන්නා වෙතින් ලබා ගන්නා ලදී',
  'Fetch details to preview' => 'පෙරදසුන් කිරීමට විස්තර ලබා ගන්න',
  'Provider thumbnails are saved as remote metadata.' => 'සපයන්නාගේ සිඟිති රූ දුරස්ථ පාර-දත්ත ලෙස සුරකිනු ලැබේ.',
