  'You are live' => 'ඔබ සජීවී ය',
  'Your camera and microphone are publishing through LiveKit.' => 'ඔබේ කැමරාව සහ මයික්‍රෆෝනය LiveKit හරහා ප්‍රකාශනය වේ.',
